namespace Mbb.Archive.Modules.Audit.Infrastructure;internal sealed class AuditEventConsumer:BackgroundService{private readonly RabbitMqConnection _rabbit;private readonly IServiceScopeFactory _scopes;private readonly TimeProvider _time;public AuditEventConsumer(RabbitMqConnection r,IServiceScopeFactory s,TimeProvider t){_rabbit=r;_scopes=s;_time=t;}protected override async Task ExecuteAsync(CancellationToken ct){await using var ch=await _rabbit.CreateConsumerChannelAsync(ct);await ch.BasicQosAsync(0,1,false,ct);var c=new AsyncEventingBasicConsumer(ch);c.ReceivedAsync+=async(_,d)=>{try{await Persist(d,ct);await ch.BasicAckAsync(d.DeliveryTag,false,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){throw;}catch{await Task.Delay(2000,ct);await ch.BasicNackAsync(d.DeliveryTag,false,true,ct);}};await ch.BasicConsumeAsync("mbb.archive.audit.events.v1",false,c,ct);await Task.Delay(Timeout.InfiniteTimeSpan,ct);}private async Task Persist(BasicDeliverEventArgs d,CancellationToken ct){var payload=Encoding.UTF8.GetString(d.Body.Span);var messageId=Guid.TryParse(d.BasicProperties.MessageId,out var parsed)?parsed:DeterministicGuid(payload);await using var scope=_scopes.CreateAsyncScope();var writer=scope.ServiceProvider.GetRequiredService<AuditJournalWriter>();
await writer.AppendAsync(messageId,d.BasicProperties.Type??"unknown",payload,
DateTimeOffset.FromUnixTimeSeconds(d.BasicProperties.Timestamp.UnixTime),ct);}
